package db

import (
	"context"
	")
)

type Grocery struct {
	ID        int
	Name      string
	Quantity  int
	CreatedAt time.Time
	UpdatedAt time.Time
}

// Connect creates a new database connection.
func Connect(ctx context.Context) (*sql.DB, error) {
	return sql.Open("sqlite3", "example.db")
}

// InsertGrocery inserts a new grocery into the database.
func InsertGrocery(ctx context.Context, name string, quantity int) (int, error) {
	db, err := Connect(ctx)
	if err != nil {
		return 0, err
	}
	defer db.Close()

	tx := db.BeginTx(ctx)
	defer tx.Rollback() // In case of error, roll back changes

	stmt := `INSERT INTO groceries (name, quantity) VALUES (?, ?)`
	res, err := tx.Exec(stmt, name, quantity)
	if err != nil {
		return 0, err
	}
	id, err := res.LastInsertId()
	if err != nil {
		return 0, err
	}

	err = tx.Commit()
	if err != nil {
		return 0, err
	}
	return int(id), nil
}

// GetGroceryByID retrieves a grocery by its ID from the database.
func GetGroceryByID(ctx context.Context, id int) (*Grocery, error) {
	db, err := Connect(ctx)
	if err != nil {
		return nil, err
	}
	defer db.Close()

	stmt := `SELECT id, name, quantity, created_at, updated_at FROM groceries WHERE id = ?`
	var g Grocery
	err = db.QueryRow(stmt, id).Scan(&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt)
	if err != nil {
		return nil, err
	}
	return &g, nil
}

// UpdateGrocery updates a grocery by its ID in the database.
func UpdateGrocery(ctx context.Context, id int, name string, quantity int) error {
	db, err := Connect(ctx)
	if err != nil {
		return err
	}
	defer db.Close()

	stmt := `UPDATE groceries SET name = ?, quantity = ? WHERE id = ?`
	_,
	err = db.Exec(stmt, name, quantity, id)
	if err != nil {
		return err
	}
	return tx.Commit()
}

// DeleteGroceryByID deletes a grocery by its ID from the database.
func DeleteGroceryByID(ctx context.Context, id int) error {
	db, err := Connect(ctx)
	if err != nil {
		return err
	}
	defer db.Close()

	stmt := `DELETE FROM groceries WHERE id = ?`
	err = db.Exec(stmt, id)
	if err != nil {
		return err
	}
	return tx.Commit()
}

