	db, err := Connect(context.TODO())
	if err != nil {
		t.Fatal(err)
	}
	defer db.Close()

	id, err := InsertGrocery(context.TODO(), "apple", 5)
	if err != nil {
		t.Fatal(err)
	}

	err = UpdateGrocery(context.TODO(), id, "banana", 10)
