		t.Fatal(err)
	}
	if g.Name != "banana" || g.Quantity != 10 {
		t.Errorf("Expected ID %d, Name banana, Quantity 10 but got ID %d, Name %s, Quantity %d", id, g.ID, g.Name, g.Quantity)
