func TestDeleteGroceryByID(t *testing.T) {
	db, err := Connect(context.TODO())
	if err != nil {
		t.Fatal(err)
	}
	defer db.Close()

	id, err := InsertGrocery(context.TODO(), "apple", 5)
	if err != nil {
		t.Fatal(err)
	}

	err = DeleteGroceryByID(context.TODO(), id)
	if err != nil {
		t.Fatal(err)
	}

	g, err := GetGroceryByID(context.TODO(), id)
