package handlers

import (
	"context"
	"encoding/json"
	"net/http"
)

type Grocery struct {
	ID        int    `json:"id"`
	Name      string `json:"name"`
	Quantity  int    `json:"quantity"`
	CreatedAt time.Time
	UpdatedAt time.Time
}

func ListGroceries(w http.ResponseWriter, r *http.Request) error {
	db, err := Connect(context.TODO())
	if err != nil {
		return err
	}
	defer db.Close()

	rows, err := db.Query(`SELECT id, name, quantity, created_at, updated_at FROM groceries`)
	if err != nil {
		return err
	}
	defer rows.Close()

	var gs []Grocery
	for rows.Next() {
		var g Grocery
		err := rows.Scan(&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt)
		if err != nil {
			return err
		}
		gs = append(gs, g)
	}
	err := json.NewEncoder(w).Encode(gs)
	if err != nil {
		return err
	}
	return nil
}

func GetGroceryByID(w http.ResponseWriter, r *http.Request) error {
	db, err := Connect(context.TODO())
	if err != nil {
		return err
	}
	defer db.Close()

	id := GetParamInt(r, "id")
	if id <= 0 {
		return http.ErrInvalidArgument
	}

	g, err := GetGroceryByID(context.TODO(), id)
	if g == nil {
		return http.StatusNotFound
	}
	err = json.NewEncoder(w).Encode(g)
	if err != nil {
		return err
	}
	return nil
}

func CreateGrocery(w http.ResponseWriter, r *http.Request) error {
	var g Grocery

	err := json.NewDecoder(r.Body).Decode(&g)
	if err != nil {
		return err
	}

	id, err := InsertGrocery(context.TODO(), g.Name, g.Quantity)
	if err != nil {
		return err
	}
	g.ID = id
	err = json.NewEncoder(w).Encode(g)
 if err != nil {
		return err
	}
 return nil
}

func UpdateGrocery(w http.ResponseWriter, r *http.Request) error {
	var g Grocery

	err := json.NewDecoder(r.Body).Decode(&g)
	if err != nil {
		return err
	}

	id, err := GetParamInt(r, "id")
	if id <= 0 {
		return http.ErrInvalidArgument
	}

	err = UpdateGrocery(context.TODO(), id, g.Name, g.Quantity)
	if err != nil {
		return err
	}
	err = json.NewEncoder(w).Encode(g)
	if err != nil {
		return err
	}
 return nil
}

func DeleteGroceryByID(w http.ResponseWriter, r *http.Request) error {
	id := GetParamInt(r, "id")
	if id <= 0{
		return http.ErrInvalidArgument
	}

	err := DeleteGroceryByID(context.TODO(),id)
	if err != nil {
		return err
	}
 return nil
}

func GetParamInt(r *http.Request, param string) int {
	val := r.URL.Query().Get(param)
	id, err := strconv.Atoi(val)
	if err != nil {
		return -1
	}
	return id
}

func RegisterRoutes(r *http.ServeMux) {
	r.HandleFunc("/groceries", ListGroceries)
	r.HandleFunc("/groceries/{id}", GetGroceryByID)
	r.HandleFunc("/groceries", CreateGrocery)
	r.HandleFunc("/groceries/{id}", UpdateGrocery)
	r.HandleFunc("/groceries/{id}", DeleteGroceryByID)
}

