package db

import (
	"errors"
	"fmt"
	"/sql"

	"github.com/lib/pq"
)

var (
	db *sql.DB
	err error
)

func Init() {
	connStr := fmt.Sprintf("host=%s port=%d user=%s password=%s dbname=%s sslmode=disable",
		"localhost", 5432, "yourusername", "yourpassword", "yourdbname")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		panic(err)
	}
}

func createGrocery(name string, quantity int) (*Grocery, error) {
	var grocery Grocery
	err := db.QueryRow(
		`INSERT INTO groceries (name, quantity) VALUES ($1, $2) RETURNING id, name, quantity, created_at, updated_at`,
		name, quantity).Scan(&grocery.ID, &grocery.Name, &grocery.Quantity, &grocery.CreatedAt, &grocery.UpdatedAt)
	return &grocery, err
}

func updateGrocery(id int, name string, quantity int) (*Grocery, error) {
	var grocery Grocery
	err := db.QueryRow(
		`UPDATE groceries SET name=$1, quantity=$2 WHERE id=$3 RETURNING id, name, quantity, created_at, updated_at`,
		name, quantity, id).Scan(&grocery.ID, &grocery.Name, &grocery.Quantity, &grocery.CreatedAt, &grocery.UpdatedAt)
	return &grocery, err
}

func deleteGrocery(id int) error {
	_, a statement to execute the query
 stmt, err := db.Prepare(`DELETE FROM groceries WHERE id=$1`)
 if err != nil {
	return err
	}
	defer stmt.Close()

	_,
	err := stmt.Exec(id)
	if err != nil {
		return err
	}
	return nil
}

func listGroceries() ([]*Grocery, error) {
	var grocerys []*Grocery
	rows, err := db.Query("SELECT id, name, quantity, created_at, updated_at FROM groceries")
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	for rows.Next() {
		var grocery Grocery
		err := rows.Scan(&grocery.ID, &grocery.Name, &grocery.Quantity, &grocery.CreatedAt, &grocery.UpdatedAt)
		if err != nil {
			return nil, err
		}
		grocerys = append(grocerys, &grocery)
	}

	return grocerys, nil
}

func getGrocery(id int) (*Grocery, error) {
	var grocery Grocery
	err := db.QueryRow(
		`SELECT id, name, quantity, created_at, updated_at FROM groceries WHERE id=$1`,
		id).Scan(&grocery.ID, &grocery.Name, &grocery.Quantity, &grocery.CreatedAt, &grocery.UpdatedAt)
	if err != nil {
		return nil, errors.New("not found")
	}
	return &grocery, nil
}

