package db

import (
	"database/sql"
)

type Grocery struct {
	ID          int       `db:"id"`
	Name        string    `db:"name"`
	Quantity    int       `db:"quantity"`
	CreatedAt   time.Time `db:"created_at"`
	UpdatedAt   time.Time `db:"updated_at"`
}

func CreateGrocery(db *sql.DB, name string, quantity int) (int, error) {
	var id int
	err := db.QueryRow(`
		INSERT INTO groceries (name, quantity)
		VALUES ($1, $2)
		RETURNING id
	`, name, quantity).Scan(&id)
	return id, err
}

func GetGrocery(db *sql.DB, id int) (*Grocery, error) {
	var g Grocery
	err := db.Get(&g, `
		SELECT id, name, quantity, created_at, updated_at
		FROM groceries
		WHERE id = $1
	`, id)
	return &g, err
}

func ListGroceries(db *sql.DB) ([]*Grocery, error) {
	var gs []*Grocery
	err := db.Select(&gs, "SELECT id, name, quantity, created_at, updated_at FROM groceries")
	return gs, err
}

func UpdateGrocery(db *sql.DB, id int, name string, quantity int) error {
	_, err := db.Exec(`
		UPDATE groceries
		SET name = $2, quantity = $3, updated_at = NOW()
		WHERE id = $1
	`, id, name, quantity)
	return err
}

func DeleteGrocery(db *sql.DB, id int) error {
	_, err := db.Exec("DELETE FROM groceries WHERE id = $1", id)
	return err
}

