package db

import (
	"database/sql"
	"errors"
)

type Grocery struct {
	ID        int       `db:"id"`
	Name      string    `db:"name"`
	Quantity  int       `db:"quantity"`
	CreatedAt sql.NullTime
	UpdatedAt sql.NullTime
}

func NewGrocery(name string, quantity int) *Grocery {
	return &Grocery{
		Name:     name,
		Quantity: quantity,
	}
}

func (g *Grocery) Save(db *sql.DB) error {
	if g.ID == 0 {
		return errors.New("ID must be set for saving")
	}
	_, err := db.Exec(`
		INSERT INTO groceries (id, name, quantity)
		VALUES ($1, $2, $3)
	`, g.ID, g.Name, g.Quantity)
	return err
}

func (g *Grocery) Update(db *sql.DB) error {
	if g.ID == 0 {
		return errors.New("ID must be set for updating")
	}
	_, err := db.Exec(`
		UPDATE groceries
		SET name = $2, quantity = $3, updated_at = NOW()
		WHERE id = $1
	`, g.ID, g.Name, g.Quantity)
	return err
}

func DeleteGrocery(db *sql.DB, id int) error {
	_, err := db.Exec("DELETE FROM groceries WHERE id = $1", id)
	return err
}

func GetGrocery(db *sql.DB, id int) (*Grocery, error) {
	var g Grocery
	err := db.Get(&g, "SELECT * FROM groceries WHERE id = $1", id)
	if errors.Is(err, sql.ErrNoRows) {
		return nil, errors.New("grocery not found")
	}
	return &g, err
}

func ListGroceries(db *sql.DB) ([]*Grocery, error) {
	var groceries []*Grocery
	err := db.Select(&groceries, "SELECT * FROM groceries")
	return groceries, err
}

