package db

import (
	"database/sql"
)

// Grocery represents a grocery item in the database.
type Grocery struct {
	ID        int       `db:"id"`
	Name      string    `db:"name"`
	Quantity  int       `db:"quantity"`
	CreatedAt sql.NullTime
	UpdatedAt sql.NullTime
}

// GetGrocery retrieves a grocery by its ID.
func GetGrocery(db *sql.DB, id int) (*Grocery, error) {
	var g Grocery
	err := db.Get(&g, "SELECT id, name, quantity, created_at, updated_at FROM groceries WHERE id = ?", id)
	if err != nil {
		return nil, err
	}
	return &g, nil
}

// ListGroceries retrieves all groceries.
func ListGroceries(db *sql.DB) ([]*Grocery, error) {
	var gs []*Grocery
	err := db.Select(&gs, "SELECT id, name, quantity, created_at, updated_at FROM groceries")
	if err != nil {
		return nil, err
	}
	return gs, nil
}

// CreateGrocery inserts a new grocery into the database.
func CreateGrocery(db *sql.DB, name string, quantity int) (*Grocery, error) {
	var g Grocery
	err := db.Get(&g, "INSERT INTO groceries (name, quantity) VALUES (?, ?) RETURNING id, name, quantity, created_at, updated_at", name, quantity)
	if err != nil {
		return nil, err
	}
	return &g, nil
}

// UpdateGrocery updates an existing grocery in the database.
func UpdateGrocery(db *sql.DB, id int, name string, quantity int) (*Grocery, error) {
	var g Grocery
	err := db.Get(&g, "UPDATE groceries SET name = ?, quantity = ? WHERE id = ? RETURNING id, name, quantity, created_at, updated_at", name, quantity, id)
	if err != nil {
		return nil, err
	}
	return &g, nil
}

// DeleteGrocery removes a grocery from the database.
func DeleteGrocery(db *sql.DB, id int) error {
	_, err := db.Exec("DELETE FROM groceries WHERE id = ?", id)
	return err
}

