package db

import (
	"database/sql"
	"time"
)

type Grocery struct {
	ID        int       `db:"id"`
	Name      string    `db:"name"`
	Quantity  int       `db:"quantity"`
	CreatedAt time.Time `db:"created_at"`
	UpdatedAt time.Time `db:"updated_at"`
}

type GroceryRepo struct {
	db *sql.DB
}

func NewGroceryRepo(db *sql.DB) *GroceryRepo {
	return &GroceryRepo{db: db}
}

func (r *GroceryRepo) GetByID(id int) (*Grocery, error) {
	var g Grocery
	err := r.db.Get(&g, "SELECT id, name, quantity, created_at, updated_at FROM groceries WHERE id = ?", id)
	if err != nil {
		return nil, err
	}
	return &g, nil
}

func (r *GroceryRepo) List() ([]*Grocery, error) {
	var gs []*Grocery
	err := r.db.Select(&gs, "SELECT id, name, quantity, created_at, updated_at FROM groceries")
	if err != nil {
		return nil, err
	}
	return gs, nil
}

func (r *GroceryRepo) Create(name string, quantity int) (*Grocery, error) {
	var g Grocery
	err := r.db.Get(&g, "INSERT INTO groceries (name, quantity) VALUES ($1, $2) RETURNING id, name, quantity, created_at, updated_at", name, quantity)
	if err != nil {
		return nil, err
	}
	return &g, nil
}

func (r *GroceryRepo) Update(id int, name string, quantity int) (*Grocery, error) {
	var g Grocery
	err := r.db.Get(&g, "UPDATE groceries SET name = $1, quantity = $2 WHERE id = $3 RETURNING id, name, quantity, created_at, updated_at", name, quantity, id)
	if err != nil {
		return nil, err
	}
	return &g, nil
}

func (r *GroceryRepo) Delete(id int) error {
	_, err := r.db.Exec("DELETE FROM groceries WHERE id = ?", id)
	return err
}

