package db

import (
	"database/sql"
	"fmt"
)

type Grocery struct {
	ID          int
	Name        string
	Quantity    int
	CreatedAt   time.Time
	UpdatedAt   time.Time
}

func GetGrocery(db *sql.DB, id int) (Grocery, error) {
	var g Grocery
	err := db.QueryRow("SELECT id, name, quantity, created_at, updated_at FROM groceries WHERE id = $1", id).Scan(&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt)
	if err != nil {
		return g, fmt.Errorf("failed to get grocery by id %d: %w", id, err)
	}
	return g, nil
}

func ListGroceries(db *sql.DB) ([]Grocery, error) {
	rows, err := db.Query("SELECT id, name, quantity, created_at, updated_at FROM groceries")
	if err != nil {
		return nil, fmt.Errorf("failed to list groceries: %w", err)
	}
	defer rows.Close()

	var groceries []Grocery
	for rows.Next() {
		var g Grocery
		err := rows.Scan(&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt)
		if err != nil {
			return nil, fmt.Errorf("failed to scan grocery row: %w", err)
		}
		groceries = append(groceries, g)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("rows error: %w", err)
	}
	return groceries, nil
}

func CreateGrocery(db *sql.DB, name string, quantity int) (int, error) {
	result, err := db.Exec("INSERT INTO groceries (name, quantity) VALUES ($1, $2) RETURNING id", name, quantity)
	if err != nil {
		return 0, fmt.Errorf("failed to create grocery: %w", err)
	}
	id, err := result.LastInsertId()
	if err != nil {
		return 0, fmt.Errorf("failed to get last insert id: %w", err)
	}
	return int(id), nil
}

func UpdateGrocery(db *sql.DB, id int, name string, quantity int) error {
	_, err := db.Exec("UPDATE groceries SET name = $2, quantity = $3 WHERE id = $1", id, name, quantity)
	if err != nil {
		return fmt.Errorf("failed to update grocery by id %d: %w", id, err)
	}
	return nil
}

func DeleteGrocery(db *sql.DB, id int) error {
	result, err := db.Exec("DELETE FROM groceries WHERE id = $1", id)
	if err != nil {
		return fmt.Errorf("failed to delete grocery by id %d: %w", id, err)
	}
	rowsAffected, err := result.RowsAffected()
	if err != nil {
		return fmt.Errorf("failed to get rows affected: %w", err)
	}
	if rowsAffected == 0 {
		return fmt.Errorf("no grocery found with id %d", id)
	}
	return nil
}

