package handlers

import (
	"database/sql"
	"encoding/json"
	"net/http"

	"github.com/gorilla/mux"
)

func ListGroceriesHandler(db *sql.DB) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		groceries, err := db.ListGroceries()
		if err != nil {
			http.Error(w, fmt.Sprintf("Failed to list groceries: %v", err), http.StatusInternalServerError)
			return
		}
		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(groceries)
	}
}

func GetGroceryHandler(db *sql.DB) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		id := mux.Vars(r)["id"]
		grocery, err := db.GetGrocery(id)
		if err != nil {
			http.Error(w, fmt.Sprintf("Failed to get grocery: %v", err), http.StatusNotFound)
			return
		}
		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(grocery)
	}
}

func CreateGroceryHandler(db *sql.DB) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		var grocery struct {
			Name     string `json:"name"`
			Quantity int    `json:"quantity"`
		}
		err := json.NewDecoder(r.Body).Decode(&grocery)
		if err != nil {
			http.Error(w, fmt.Sprintf("Failed to decode grocery: %v", err), http.StatusBadRequest)
			return
		}
		id, err := db.CreateGrocery(grocery.Name, grocery.Quantity)
		if err != nil {
			http.Error(w, fmt.Sprintf("Failed to create grocery: %v", err), http.StatusInternalServerError)
			return
		}
		w.WriteHeader(http.StatusCreated)
		json.NewEncoder(w).Encode(map[string]interface{}{"id": id})
	}
}

func UpdateGroceryHandler(db *sql.DB) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		id := mux.Vars(r)["id"]
		var grocery struct {
			Name     string `json:"name"`
			Quantity int    `json:"quantity"`
		}
		err := json.NewDecoder(r.Body).Decode(&grocery)
		if err != nil {
			http.Error(w, fmt.Sprintf("Failed to decode grocery: %v", err), http.StatusBadRequest)
			return
		}
		err = db.UpdateGrocery(id, grocery.Name, grocery.Quantity)
		if err != nil {
			http.Error(w, fmt.Sprintf("Failed to update grocery: %v", err), http.StatusInternalServerError)
			return
		}
		w.WriteHeader(http.StatusNoContent)
	}
}

func DeleteGroceryHandler(db *sql.DB) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		id := mux.Vars(r)["id"]
		err := db.DeleteGrocery(id)
		if err != nil {
			http.Error(w, fmt.Sprintf("Failed to delete grocery: %v", err), http.StatusInternalServerError)
			return
		}
		w.WriteHeader(http.StatusNoContent)
	}
}

