package db

import (
	"database/sql"
)

type Grocery struct {
	ID        int           `db:"id"`
	Name      string        `db:"name"`
	Quantity  int           `db:"quantity"`
	CreatedAt sql.NullTime  `db:"created_at"`
	UpdatedAt sql.NullTime  `db:"updated_at"`
}

func GetGroceryByID(db *sql.DB, id int) (*Grocery, error) {
	var grocery Grocery
	err := db.Get(&grocery, "SELECT id, name, quantity, created_at, updated_at FROM groceries WHERE id = ?", id)
	if err != nil {
		return nil, err
	}
	return &grocery, nil
}

func ListGroceries(db *sql.DB) ([]*Grocery, error) {
	var groceries []*Grocery
	err := db.Select(&groceries, "SELECT id, name, quantity, created_at, updated_at FROM groceries")
	if err != nil {
		return nil, err
	}
	return groceries, nil
}

func CreateGrocery(db *sql.DB, name string, quantity int) (*Grocery, error) {
	var grocery Grocery
	err := db.Get(&grocery, "INSERT INTO groceries (name, quantity) VALUES ($1, $2) RETURNING id", name, quantity)
	if err != nil {
		return nil, err
	}
	grocery.Name = name
	grocery.Quantity = quantity
	return &grocery, nil
}

func UpdateGrocery(db *sql.DB, id int, name string, quantity int) (*Grocery, error) {
	var grocery Grocery
	err := db.Get(&grocery, "UPDATE groceries SET name = $1, quantity = $2 WHERE id = $3 RETURNING id", name, quantity, id)
	if err != nil {
		return nil, err
	}
	grocery.Name = name
	grocery.Quantity = quantity
	return &grocery, nil
}

func DeleteGrocery(db *sql.DB, id int) error {
	result, err := db.Exec("DELETE FROM groceries WHERE id = ?", id)
	if err != nil {
		return err
	}
	rowsAffected, _ := result.RowsAffected()
	if rowsAffected == 0 {
		return sql.ErrNoRows
	}
	return nil
}

