package db

import (
	"database/sql"
	"time"

	_ "github.com/lib/pq"
)

type Grocery struct {
	ID          int       `db:"id"`
	Name        string    `db:"name"`
	Quantity    int       `db:"quantity"`
	CreatedAt   time.Time `db:"created_at"`
	UpdatedAt   time.Time `db:"updated_at"`
}

type DB struct {
	db *sql.DB
}

func NewDB(dataSourceName string) (*DB, error) {
	db, err := sql.Open("postgres", dataSourceName)
	if err != nil {
		return nil, err
	}
	return &DB{db: db}, nil
}

func (d *DB) Close() error {
	return d.db.Close()
}

func (d *DB) GetGrocery(id int) (*Grocery, error) {
	var g Grocery
	err := d.db.Get(&g, "SELECT * FROM groceries WHERE id = $1", id)
	if err != nil {
		return nil, err
	}
	return &g, nil
}

func (d *DB) ListGroceries() ([]*Grocery, error) {
	var gs []*Grocery
	err := d.db.Select(&gs, "SELECT * FROM groceries")
	if err != nil {
		return nil, err
	}
	return gs, nil
}

func (d *DB) CreateGrocery(name string, quantity int) (*Grocery, error) {
	var g Grocery
	err := d.db.Get(&g, "INSERT INTO groceries (name, quantity) VALUES ($1, $2) RETURNING *", name, quantity)
	if err != nil {
		return nil, err
	}
	return &g, nil
}

func (d *DB) UpdateGrocery(id int, name string, quantity int) (*Grocery, error) {
	var g Grocery
	err := d.db.Get(&g, "UPDATE groceries SET name = $1, quantity = $2 WHERE id = $3 RETURNING *", name, quantity, id)
	if err != nil {
		return nil, err
	}
	return &g, nil
}

func (d *DB) DeleteGrocery(id int) error {
	_, err := d.db.Exec("DELETE FROM groceries WHERE id = $1", id)
	return err
}

