type Grocery struct {
	ID        int64  `db:"id"`
	Name      string `db:"name"`
	Quantity  int    `db:"quantity"`
	CreatedAt time.Time
	UpdatedAt time.Time
}

func (d *DB) GetGrocery(id int64) (*Grocery, error) {
	var g Grocery
	err := d.q.Get(&g, "SELECT * FROM groceries WHERE id=$1", id)
	if err == sql.ErrNoRows {
		return nil, ErrNotFound
	}
	return &g, err
}

func (d *DB) ListGroceries() ([]*Grocery, error) {
	var gs []*Grocery
	err := d.q.Select(&gs, "SELECT * FROM groceries")
	return gs, err
}

func (d *DB) CreateGrocery(name string, quantity int) (*Grocery, error) {
	var g Grocery
	err := d.q.Get(&g, `
	INSERT INTO groceries (name, quantity)
	VALUES ($1, $2)
	RETURNING id, name, quantity, created_at, updated_at
	`, name, quantity)
	return &g, err
}

func (d *DB) UpdateGrocery(id int64, name string, quantity int) (*Grocery, error) {
	var g Grocery
	err := d.q.Get(&g, `
	UPDATE groceries
	SET name=$2, quantity=$3
	WHERE id=$1
	RETURNING id, name, quantity, created_at, updated_at
	`, id, name, quantity)
	if err == sql.ErrNoRows {
		return nil, ErrNotFound
	}
	return &g, err
}

func (d *DB) DeleteGrocery(id int64) error {
	result, err := d.q.Exec("DELETE FROM groceries WHERE id=$1", id)
	if err != nil {
		return err
	}
	rowsAffected, _ := result.RowsAffected()
	if rowsAffected == 0 {
		return ErrNotFound
	}
	return nil
}

