package db

import (
	"database/sql"
)

type Grocery struct {
	ID          int       `db:"id"`
	Name        string    `db:"name"`
	Qty         int       `db:"quantity"`
	CreatedAt   time.Time `db:"created_at"`
	UpdatedAt   time.Time `db:"updated_at"`
}

type GroceryRepo struct {
	db *sql.DB
}

func NewGroceryRepo(db *sql.DB) *GroceryRepo {
	return &GroceryRepo{db: db}
}

func (r *GroceryRepo) List() ([]*Grocery, error) {
	rows, err := r.db.Query("SELECT id, name, quantity FROM groceries")
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var groceries []*Grocery
	for rows.Next() {
		var g Grocery
		if err := rows.Scan(&g.ID, &g.Name, &g.Qty); err != nil {
			return nil, err
		}
		groceries = append(groceries, &g)
	}

	if err := rows.Err(); err != nil {
		return nil, err
	}

	return groceries, nil
}

func (r *GroceryRepo) Get(id int) (*Grocery, error) {
	g := &Grocery{}
	if err := r.db.Get(g, "SELECT id, name, quantity FROM groceries WHERE id = $1", id); err != nil {
		return nil, err
	}
	return g, nil
}

func (r *GroceryRepo) Create(name string, qty int) (*Grocery, error) {
	g := &Grocery{Name: name, Qty: qty}
	if err := r.db.Get(g, "INSERT INTO groceries (name, quantity) VALUES ($1, $2) RETURNING id", name, qty); err != nil {
		return nil, err
	}
	return g, nil
}

func (r *GroceryRepo) Update(id int, name string, qty int) (*Grocery, error) {
	g := &Grocery{ID: id, Name: name, Qty: qty}
	if err := r.db.Get(g, "UPDATE groceries SET name = $1, quantity = $2 WHERE id = $3 RETURNING id", name, qty, id); err != nil {
		return nil, err
	}
	return g, nil
}

func (r *GroceryRepo) Delete(id int) error {
	_, err := r.db.Exec("DELETE FROM groceries WHERE id = $1", id)
	return err
}

