package db

import (
    "database/sql"
    "errors"

    _ "github.com/lib/pq"
)

const (
    createTableSQL = `CREATE TABLE IF NOT EXISTS groceries (
        id serial PRIMARY KEY,
        name text NOT NULL,
        quantity integer NOT NULL DEFAULT 0
    )`
)

type Grocery struct {
    ID         int       `db:"id"`
    Name       string    `db:"name"`
    Quantity   int       `db:"quantity"`
    CreatedAt  time.Time `db:"created_at"`
    UpdatedAt  time.Time `db:"updated_at"`
}

func Init(db *sql.DB) error {
    _, err := db.Exec(createTableSQL)
    return err
}

func GetByID(db *sql.DB, id int) (*Grocery, error) {
    var g Grocery
    err := db.Get(&g, "SELECT * FROM groceries WHERE id = $1", id)
    if err == sql.ErrNoRows {
        return nil, errors.New("grocery not found")
    }
    if err != nil {
        return nil, err
    }
    return &g, nil
}

func List(db *sql.DB) ([]*Grocery, error) {
    var groceries []*Grocery
    err := db.Select(&groceries, "SELECT * FROM groceries")
    if err != nil {
        return nil, err
    }
    return groceries, nil
}

func Create(db *sql.DB, name string, quantity int) (*Grocery, error) {
    var g Grocery
    err := db.Get(&g, "INSERT INTO groceries (name, quantity) VALUES ($1, $2) RETURNING *", name, quantity)
    if err != nil {
        return nil, err
    }
    return &g, nil
}

func UpdateByID(db *sql.DB, id int, name string, quantity int) (*Grocery, error) {
    var g Grocery
    err := db.Get(&g, "UPDATE groceries SET name = $2, quantity = $3 WHERE id = $1 RETURNING *", id, name, quantity)
    if err != nil {
        return nil, err
    }
    return &g, nil
}

func DeleteByID(db *sql.DB, id int) error {
    res, err := db.Exec("DELETE FROM groceries WHERE id = $1", id)
    if err != nil {
        return err
    }
    rowsAffected, err := res.RowsAffected()
    if err != nil {
        return err
    }
    if rowsAffected == 0 {
        return errors.New("grocery not found")
    }
    return nil
}

