package db

import (
	"database/sql"
)

type Grocery struct {
	ID          int     `json:"id"`
	Name        string  `json:"name"`
	Quantity    int     `json:"quantity"`
	CreatedAt   sql.NullTime
	UpdatedAt   sql.NullTime
}

type GroceriesDB interface {
	ListGroceries() ([]*Grocery, error)
	GetGrocery(id int) (*Grocery, error)
	CreateGrocery(name string, quantity int) (int, error)
	UpdateGrocery(id int, name string, quantity int) error
	DeleteGrocery(id int) error
}

type groceriesDB struct {
	db *sql.DB
}

func NewGroceriesDB(db *sql.DB) GroceriesDB {
	return &groceriesDB{db: db}
}

func (g *groceriesDB) ListGroceries() ([]*Grocery, error) {
	rows, err := g.db.Query("SELECT id, name, quantity, created_at, updated_at FROM groceries")
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var groceries []*Grocery
	for rows.Next() {
		var grocery Grocery
		if err := rows.Scan(&grocery.ID, &grocery.Name, &grocery.Quantity, &grocery.CreatedAt, &grocery.UpdatedAt); err != nil {
			return nil, err
		}
		groceries = append(groceries, &grocery)
	}

	if err := rows.Err(); err != nil {
		return nil, err
	}

	return groceries, nil
}

func (g *groceriesDB) GetGrocery(id int) (*Grocery, error) {
	var grocery Grocery
	err := g.db.QueryRow("SELECT id, name, quantity, created_at, updated_at FROM groceries WHERE id = $1", id).Scan(&grocery.ID, &grocery.Name, &grocery.Quantity, &grocery.CreatedAt, &grocery.UpdatedAt)
	if err != nil {
		return nil, err
	}
	return &grocery, nil
}

func (g *groceriesDB) CreateGrocery(name string, quantity int) (int, error) {
	result, err := g.db.Exec("INSERT INTO groceries (name, quantity) VALUES ($1, $2) RETURNING id", name, quantity)
	if err != nil {
		return 0, err
	}
	id, _ := result.LastInsertId()
	return int(id), nil
}

func (g *groceriesDB) UpdateGrocery(id int, name string, quantity int) error {
	_, err := g.db.Exec("UPDATE groceries SET name = $1, quantity = $2 WHERE id = $3", name, quantity, id)
	return err
}

func (g *groceriesDB) DeleteGrocery(id int) error {
	_, err := g.db.Exec("DELETE FROM groceries WHERE id = $1", id)
	return err
}

