package handlers

import (
	"encoding/json"
	"net/http"

	"github.com/jmoiron/sqlx"
)

type Grocery struct {
	ID        int       `json:"id"`
	Name      string    `json:"name"`
	Quantity  int       `json:"quantity"`
	CreatedAt time.Time `json:"created_at"`
	UpdatedAt time.Time `json:"updated_at"`
}

func ListGroceries(db *sqlx.DB) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		groceries, err := GetGroceries(db)
		if err != nil {
			http.Error(w, err.Error(), http.StatusInternalServerError)
			return
		}
		json.NewEncoder(w).Encode(groceries)
	}
}

func GetGroceryByIDHandler(db *sqlx.DB) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		id := getIDFromRequest(r)
		grocery, err := GetGroceryByID(db, id)
		if err != nil {
			http.Error(w, err.Error(), http.StatusInternalServerError)
			return
		}
		if grocery == nil {
			http.NotFound(w, r)
			return
		}
		json.NewEncoder(w).Encode(grocery)
	}
}

func CreateGroceryHandler(db *sqlx.DB) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		var grocery Grocery
		err := json.NewDecoder(r.Body).Decode(&grocery)
		if err != nil {
			http.Error(w, err.Error(), http.StatusBadRequest)
			return
		}
		err = grocery.Create(db)
		if err != nil {
			http.Error(w, err.Error(), http.StatusInternalServerError)
			return
		}
		w.WriteHeader(http.StatusCreated)
		json.NewEncoder(w).Encode(grocery)
	}
}

func UpdateGroceryHandler(db *sqlx.DB) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		id := getIDFromRequest(r)
		var grocery Grocery
		err := json.NewDecoder(r.Body).Decode(&grocery)
		if err != nil {
			http.Error(w, err.Error(), http.StatusBadRequest)
			return
		}
		grocery.ID = id
		updatedGrocery, err := UpdateGrocery(db, id, grocery.Name, grocery.Quantity)
		if err != nil {
			http.Error(w, err.Error(), http.StatusInternalServerError)
			return
		}
		if updatedGrocery == nil {
			http.NotFound(w, r)
			return
		}
		json.NewEncoder(w).Encode(updatedGrocery)
	}
}

func DeleteGroceryHandler(db *sqlx.DB) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		id := getIDFromRequest(r)
		err := DeleteGrocery(db, id)
		if err != nil {
			http.Error(w, err.Error(), http.StatusInternalServerError)
			return
		}
		w.WriteHeader(http.StatusNoContent)
	}
}

func getIDFromRequest(r *http.Request) int {
	vars := r.URL.Query()
	idStr := vars.Get("id")
	id, _ := strconv.Atoi(idStr)
	return id
}

