package db

import (
	"database/sql"
	"time"

	"github.com/jmoiron/sqlx"
)

type Grocery struct {
	ID        int       `db:"id"`
	Name      string    `db:"name"`
	Quantity  int       `db:"quantity"`
	CreatedAt time.Time `db:"created_at"`
	UpdatedAt time.Time `db:"updated_at"`
}

func (db *DB) GetGrocery(id int) (*Grocery, error) {
	var grocery Grocery
	err := db.Get(&grocery, "SELECT * FROM groceries WHERE id = $1", id)
	if err == sql.ErrNoRows {
		return nil, nil
	}
	return &grocery, err
}

func (db *DB) ListGroceries() ([]Grocery, error) {
	var groceries []Grocery
	err := db.Select(&groceries, "SELECT * FROM groceries")
	return groceries, err
}

func (db *DB) CreateGrocery(name string, quantity int) (*Grocery, error) {
	var grocery Grocery
	query := `
		INSERT INTO groceries (name, quantity)
		VALUES ($1, $2)
		RETURNING id, name, quantity, created_at, updated_at
	`
	err := db.Get(&grocery, query, name, quantity)
	return &grocery, err
}

func (db *DB) UpdateGrocery(id int, name string, quantity int) (*Grocery, error) {
	var grocery Grocery
	query := `
		UPDATE groceries
		SET name = $2, quantity = $3, updated_at = CURRENT_TIMESTAMP
		WHERE id = $1
		RETURNING id, name, quantity, created_at, updated_at
	`
	err := db.Get(&grocery, query, id, name, quantity)
	if err == sql.ErrNoRows {
		return nil, nil
	}
	return &grocery, err
}

func (db *DB) DeleteGrocery(id int) error {
	result, err := db.Exec("DELETE FROM groceries WHERE id = $1", id)
	if err != nil {
		return err
	}
	rowsAffected, err := result.RowsAffected()
	if rowsAffected == 0 {
		return sql.ErrNoRows
	}
	return nil
}

