package handlers

import (
	"encoding/json"
	"net/http"

	"github.com/jmoiron/sqlx"
	"github.com/yourusername/yourapp/db"
)

type GroceriesHandler struct {
	DB *db.DB
}

func (h *GroceriesHandler) List(w http.ResponseWriter, r *http.Request) {
	groceries, err := h.DB.ListGroceries()
	if err != nil {
		http.Error(w, "Failed to list groceries", http.StatusInternalServerError)
		return
	}
	json.NewEncoder(w).Encode(groceries)
}

func (h *GroceriesHandler) Get(w http.ResponseWriter, r *http.Request) {
	id := getIDFromRequest(r)
	grocery, err := h.DB.GetGrocery(id)
	if err != nil {
		http.Error(w, "Failed to get grocery", http.StatusInternalServerError)
		return
	}
	if grocery == nil {
		http.NotFound(w, r)
		return
	}
	json.NewEncoder(w).Encode(grocery)
}

func (h *GroceriesHandler) Create(w http.ResponseWriter, r *http.Request) {
	var grocery db.Grocery
	if err := json.NewDecoder(r.Body).Decode(&grocery); err != nil {
		http.Error(w, "Invalid request body", http.StatusBadRequest)
		return
	}
	newGrocery, err := h.DB.CreateGrocery(grocery.Name, grocery.Quantity)
	if err != nil {
		http.Error(w, "Failed to create grocery", http.StatusInternalServerError)
		return
	}
	w.WriteHeader(http.StatusCreated)
	json.NewEncoder(w).Encode(newGrocery)
}

func (h *GroceriesHandler) Update(w http.ResponseWriter, r *http.Request) {
	id := getIDFromRequest(r)
	var grocery db.Grocery
	if err := json.NewDecoder(r.Body).Decode(&grocery); err != nil {
		http.Error(w, "Invalid request body", http.StatusBadRequest)
		return
	}
	updatedGrocery, err := h.DB.UpdateGrocery(id, grocery.Name, grocery.Quantity)
	if err != nil {
		if err == sql.ErrNoRows {
			http.NotFound(w, r)
		} else {
			http.Error(w, "Failed to update grocery", http.StatusInternalServerError)
		}
		return
	}
	json.NewEncoder(w).Encode(updatedGrocery)
}

func (h *GroceriesHandler) Delete(w http.ResponseWriter, r *http.Request) {
	id := getIDFromRequest(r)
	err := h.DB.DeleteGrocery(id)
	if err != nil {
		if err == sql.ErrNoRows {
			http.NotFound(w, r)
		} else {
			http.Error(w, "Failed to delete grocery", http.StatusInternalServerError)
		}
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

func getIDFromRequest(r *http.Request) int {
	idStr := r.URL.Path[len("/groceries/"):]
	id, _ := strconv.Atoi(idStr)
	return id
}

