package db

import (
	"database/sql"
	"fmt"

	_ "github.com/lib/pq"
)

type Grocery struct {
	ID         int       `json:"id"`
	Name       string    `json:"name"`
	Quantity   int       `json:"quantity"`
	CreatedAt  sql.NullTime `json:"created_at"`
	UpdatedAt  sql.NullTime `json:"updated_at"`
}

func GetGroceries(db *sql.DB) ([]Grocery, error) {
	rows, err := db.Query("SELECT id, name, quantity, created_at, updated_at FROM groceries ORDER BY id")
	if err != nil {
		return nil, fmt.Errorf("failed to query groceries: %v", err)
	}
	defer rows.Close()

	var groceries []Grocery
	for rows.Next() {
		var grocery Grocery
		if err := rows.Scan(&grocery.ID, &grocery.Name, &grocery.Quantity, &grocery.CreatedAt, &grocery.UpdatedAt); err != nil {
			return nil, fmt.Errorf("failed to scan row: %v", err)
		}
		groceries = append(groceries, grocery)
	}

	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("row error: %v", err)
	}

	return groceries, nil
}

func GetGroceryByID(db *sql.DB, id int) (*Grocery, error) {
	var grocery Grocery
	err := db.QueryRow("SELECT id, name, quantity, created_at, updated_at FROM groceries WHERE id = $1", id).
		Scan(&grocery.ID, &grocery.Name, &grocery.Quantity, &grocery.CreatedAt, &grocery.UpdatedAt)
	if err != nil {
		if err == sql.ErrNoRows {
			return nil, fmt.Errorf("grocery not found: %v", err)
		}
		return nil, fmt.Errorf("failed to query grocery by id: %v", err)
	}

	return &grocery, nil
}

func CreateGrocery(db *sql.DB, name string, quantity int) (*Grocery, error) {
	var grocery Grocery
	err := db.QueryRow("INSERT INTO groceries (name, quantity) VALUES ($1, $2) RETURNING id, name, quantity, created_at, updated_at",
		name, quantity).
		Scan(&grocery.ID, &grocery.Name, &grocery.Quantity, &grocery.CreatedAt, &grocery.UpdatedAt)
	if err != nil {
		return nil, fmt.Errorf("failed to create grocery: %v", err)
	}

	return &grocery, nil
}

func UpdateGrocery(db *sql.DB, id int, name string, quantity int) (*Grocery, error) {
	var grocery Grocery
	err := db.QueryRow("UPDATE groceries SET name = $1, quantity = $2 WHERE id = $3 RETURNING id, name, quantity, created_at, updated_at",
		name, quantity, id).
		Scan(&grocery.ID, &grocery.Name, &grocery.Quantity, &grocery.CreatedAt, &grocery.UpdatedAt)
	if err != nil {
		if err == sql.ErrNoRows {
			return nil, fmt.Errorf("grocery not found: %v", err)
		}
		return nil, fmt.Errorf("failed to update grocery: %v", err)
	}

	return &grocery, nil
}

func DeleteGrocery(db *sql.DB, id int) error {
	result, err := db.Exec("DELETE FROM groceries WHERE id = $1", id)
	if err != nil {
		return fmt.Errorf("failed to delete grocery: %v", err)
	}
	rowsAffected, err := result.RowsAffected()
	if err != nil {
		return fmt.Errorf("failed to get rows affected: %v", err)
	}
	if rowsAffected == 0 {
		return fmt.Errorf("grocery not found")
	}

	return nil
}

