func ListGroceries(w http.ResponseWriter, r *http.Request) {
	db := r.Context().Value("db").(*db.DB)
	groceries, err := db.ListGroceries()
	if err != nil {
		http.Error(w, "Failed to list groceries", http.StatusInternalServerError)
		return
	}
