}

func GetGroceryByID(w http.ResponseWriter, r *http.Request) {
	idStr := r.URL.Query().Get("id")
	id, err := strconv.Atoi(idStr)
	if err != nil || id <= 0 {
		http.Error(w, "Invalid ID", http.StatusBadRequest)
		return
	}

	db := r.Context().Value("db").(*db.DB)
	grocery, err := db.GetGroceryByID(id)
	if err != nil {
		http.Error(w, "Failed to get grocery", http.StatusInternalServerError)
		return
	}
	json.NewEncoder(w).Encode(grocery)
}

func CreateGrocery(w http.ResponseWriter, r *http.Request) {
	var grocery Grocery
	err := json.NewDecoder(r.Body).Decode(&grocery)
	if err != nil {
		http.Error(w, "Invalid request body", http.StatusBadRequest)
		return
	}

	db := r.Context().Value("db").(*db.DB)
	newGrocery, err := db.CreateGrocery(grocery.Name, grocery.Quantity)
	if err != nil {
		http.Error(w, "Failed to create grocery", http.StatusInternalServerError)
		return
	}
	json.NewEncoder(w).Encode(newGrocery)
}

func UpdateGrocery(w http.ResponseWriter, r *http.Request) {
	idStr := r.URL.Query().Get("id")
	id, err := strconv.Atoi(idStr)
	if err != nil || id <= 0 {
		http.Error(w, "Invalid ID", http.StatusBadRequest)
		return
	}

	var grocery Grocery
	err = json.NewDecoder(r.Body).Decode(&grocery)
	if err != nil {
		http.Error(w, "Invalid request body", http.StatusBadRequest)
		return
	}

	db := r.Context().Value("db").(*db.DB)
	updatedGrocery, err := db.UpdateGrocery(id, grocery.Name, grocery.Quantity)
	if err != nil {
		http.Error(w, "Failed to update grocery", http.StatusInternalServerError)
		return
	}
	json.NewEncoder(w).Encode(updatedGrocery)
}

func DeleteGrocery(w http.ResponseWriter, r *http.Request) {
	idStr := r.URL.Query().Get("id")
	id, err := strconv.Atoi(idStr)
	if err != nil || id <= 0 {
		http.Error(w, "Invalid ID", http.StatusBadRequest)
		return
	}

	db := r.Context().Value("db").(*db.DB)
	err = db.DeleteGrocery(id)
	if err != nil {
		http.Error(w, "Failed to delete grocery", http.StatusInternalServerError)
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

