package db

import (
	"database/sql"
	"fmt"

	_ "github.com/mattn/go-sqlite3"
)

type Grocery struct {
	ID         int       `json:"id"`
	Name       string    `json:"name"`
	Quantity   int       `json:"quantity"`
	CreatedAt  sql.NullTime `json:"created_at"`
	UpdatedAt  sql.NullTime `json:"updated_at"`
}

func GetGrocery(db *sql.DB, id int) (Grocery, error) {
	var grocery Grocery
	err := db.QueryRow(`SELECT id, name, quantity, created_at, updated_at FROM groceries WHERE id = ?`, id).Scan(
		&grocery.ID,
		&grocery.Name,
		&grocery.Quantity,
		&grocery.CreatedAt,
		&grocery.UpdatedAt,
	)
	if err != nil {
		return grocery, fmt.Errorf("failed to get grocery: %w", err)
	}
	return grocery, nil
}

func ListGroceries(db *sql.DB) ([]Grocery, error) {
	rows, err := db.Query(`SELECT id, name, quantity, created_at, updated_at FROM groceries`)
	if err != nil {
		return nil, fmt.Errorf("failed to list groceries: %w", err)
	}
	defer rows.Close()

	groceries := []Grocery{}
	for rows.Next() {
		var grocery Grocery
		if err := rows.Scan(
			&grocery.ID,
			&grocery.Name,
			&grocery.Quantity,
			&grocery.CreatedAt,
			&grocery.UpdatedAt,
		); err != nil {
			return nil, fmt.Errorf("failed to scan row: %w", err)
		}
		groceries = append(groceries, grocery)
	}

	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("rows error: %w", err)
	}

	return groceries, nil
}

func CreateGrocery(db *sql.DB, name string, quantity int) (int64, error) {
	result, err := db.Exec(`INSERT INTO groceries (name, quantity) VALUES (?, ?)`, name, quantity)
	if err != nil {
		return 0, fmt.Errorf("failed to create grocery: %w", err)
	}
	id, err := result.LastInsertId()
	if err != nil {
		return 0, fmt.Errorf("failed to get last insert id: %w", err)
	}
	return id, nil
}

func UpdateGrocery(db *sql.DB, id int, name string, quantity int) error {
	_, err := db.Exec(`UPDATE groceries SET name = ?, quantity = ? WHERE id = ?`, name, quantity, id)
	if err != nil {
		return fmt.Errorf("failed to update grocery: %w", err)
	}
	return nil
}

func DeleteGrocery(db *sql.DB, id int) error {
	_, err := db.Exec(`DELETE FROM groceries WHERE id = ?`, id)
	if err != nil {
		return fmt.Errorf("failed to delete grocery: %w", err)
	}
	return nil
}

