package db

import (
	"database/sql"
	"fmt"

	_ "github.com/lib/pq"
)

type Grocery struct {
	ID        int       `json:"id"`
	Name      string    `json:"name"`
	Quantity  int       `json:"quantity"`
	CreatedAt string    `json:"created_at"`
	UpdatedAt string    `json:"updated_at"`
}

func ConnectDB(dataSourceName string) (*sql.DB, error) {
	db, err := sql.Open("postgres", dataSourceName)
	if err != nil {
		return nil, fmt.Errorf("could not connect to database: %v", err)
	}
	if err = db.Ping(); err != nil {
		return nil, fmt.Errorf("failed to ping database: %v", err)
	}
	return db, nil
}

func (g *Grocery) Create(db *sql.DB) error {
	query := `INSERT INTO groceries (name, quantity) VALUES ($1, $2) RETURNING id, created_at, updated_at`
	err := db.QueryRow(query, g.Name, g.Quantity).Scan(&g.ID, &g.CreatedAt, &g.UpdatedAt)
	return err
}

func (g *Grocery) Update(db *sql.DB) error {
	query := `UPDATE groceries SET name = $1, quantity = $2, updated_at = now() WHERE id = $3 RETURNING created_at, updated_at`
	err := db.QueryRow(query, g.Name, g.Quantity, g.ID).Scan(&g.CreatedAt, &g.UpdatedAt)
	return err
}

func (g *Grocery) Delete(db *sql.DB) error {
	query := `DELETE FROM groceries WHERE id = $1`
	_, err := db.Exec(query, g.ID)
	return err
}

func GetGroceryByID(db *sql.DB, id int) (*Grocery, error) {
	grocery := &Grocery{ID: id}
	query := `SELECT name, quantity, created_at, updated_at FROM groceries WHERE id = $1`
	err := db.QueryRow(query, id).Scan(&grocery.Name, &grocery.Quantity, &grocery.CreatedAt, &grocery.UpdatedAt)
	if err == sql.ErrNoRows {
		return nil, fmt.Errorf("record not found")
	}
	return grocery, err
}

func ListGroceries(db *sql.DB) ([]*Grocery, error) {
	rows, err := db.Query(`SELECT id, name, quantity, created_at, updated_at FROM groceries`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var groceries []*Grocery
	for rows.Next() {
		grocery := &Grocery{}
		err = rows.Scan(&grocery.ID, &grocery.Name, &grocery.Quantity, &grocery.CreatedAt, &grocery.UpdatedAt)
		if err != nil {
			return nil, err
		}
		groceries = append(groceries, grocery)
	}

	return groceries, rows.Err()
}

