package handlers

import (
	"encoding/json"
	"net/http"

	"github.com/yourusername/yourproject/db"
)

func ListGroceries(db *db.DB) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		groceries, err := db.ListGroceries()
		if err != nil {
			http.Error(w, "Internal Server Error", http.StatusInternalServerError)
			return
		}
		json.NewEncoder(w).Encode(groceries)
	}
}

func GetGroceryByID(db *db.DB) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		id := getIDFromRequest(r)
		grocery, err := db.GetGroceryByID(id)
		if err != nil {
			http.Error(w, "Not Found", http.StatusNotFound)
			return
		}
		json.NewEncoder(w).Encode(grocery)
	}
}

func CreateGrocery(db *db.DB) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		var grocery db.Grocery
		err := json.NewDecoder(r.Body).Decode(&grocery)
		if err != nil {
			http.Error(w, "Bad Request", http.StatusBadRequest)
			return
		}
		grocery, err = db.CreateGrocery(grocery.Name, grocery.Quantity)
		if err != nil {
			http.Error(w, "Internal Server Error", http.StatusInternalServerError)
			return
		}
		json.NewEncoder(w).Encode(grocery)
	}
}

func UpdateGrocery(db *db.DB) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		id := getIDFromRequest(r)
		var grocery db.Grocery
		err := json.NewDecoder(r.Body).Decode(&grocery)
		if err != nil {
			http.Error(w, "Bad Request", http.StatusBadRequest)
			return
		}
		grocery, err = db.UpdateGrocery(id, grocery.Name, grocery.Quantity)
		if err != nil {
			http.Error(w, "Not Found", http.StatusNotFound)
			return
		}
		json.NewEncoder(w).Encode(grocery)
	}
}

func DeleteGrocery(db *db.DB) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		id := getIDFromRequest(r)
		err := db.DeleteGrocery(id)
		if err != nil {
			http.Error(w, "Not Found", http.StatusNotFound)
			return
		}
		w.WriteHeader(http.StatusNoContent)
	}
}

func getIDFromRequest(r *http.Request) int {
	idStr := r.URL.Query().Get("id")
	id, _ := strconv.Atoi(idStr)
	return id
}

