package db

import (
	"database/sql"
	"time"

	_ "github.com/lib/pq"
)

type Grocery struct {
	ID         int       `json:"id"`
	Name       string    `json:"name"`
	Quantity   int       `json:"quantity"`
	CreatedAt  time.Time `json:"created_at"`
	UpdatedAt  time.Time `json:"updated_at"`
}

func OpenDB(dataSourceName string) (*sql.DB, error) {
	db, err := sql.Open("postgres", dataSourceName)
	if err != nil {
		return nil, err
	}
	err = db.Ping()
	if err != nil {
		return nil, err
	}
	return db, nil
}

func (db *sql.DB) ListGroceries() ([]Grocery, error) {
	rows, err := db.Query(`SELECT id, name, quantity, created_at, updated_at FROM groceries ORDER BY id`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var groceries []Grocery
	for rows.Next() {
		var grocery Grocery
		err := rows.Scan(&grocery.ID, &grocery.Name, &grocery.Quantity, &grocery.CreatedAt, &grocery.UpdatedAt)
		if err != nil {
			return nil, err
		}
		groceries = append(groceries, grocery)
	}
	return groceries, nil
}

func (db *sql.DB) GetGroceryByID(id int) (*Grocery, error) {
	var grocery Grocery
	err := db.QueryRow(`SELECT id, name, quantity, created_at, updated_at FROM groceries WHERE id = $1`, id).Scan(&grocery.ID, &grocery.Name, &grocery.Quantity, &grocery.CreatedAt, &grocery.UpdatedAt)
	if err == sql.ErrNoRows {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}
	return &grocery, nil
}

func (db *sql.DB) CreateGrocery(name string, quantity int) (*Grocery, error) {
	var grocery Grocery
	err := db.QueryRow(`INSERT INTO groceries (name, quantity) VALUES ($1, $2) RETURNING id, name, quantity, created_at, updated_at`, name, quantity).Scan(&grocery.ID, &grocery.Name, &grocery.Quantity, &grocery.CreatedAt, &grocery.UpdatedAt)
	if err != nil {
		return nil, err
	}
	return &grocery, nil
}

func (db *sql.DB) UpdateGrocery(id int, name string, quantity int) (*Grocery, error) {
	var grocery Grocery
	err := db.QueryRow(`UPDATE groceries SET name = $1, quantity = $2 WHERE id = $3 RETURNING id, name, quantity, created_at, updated_at`, name, quantity, id).Scan(&grocery.ID, &grocery.Name, &grocery.Quantity, &grocery.CreatedAt, &grocery.UpdatedAt)
	if err == sql.ErrNoRows {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}
	return &grocery, nil
}

func (db *sql.DB) DeleteGrocery(id int) error {
	result, err := db.Exec(`DELETE FROM groceries WHERE id = $1`, id)
	if err != nil {
		return err
	}
	rowsAffected, err := result.RowsAffected()
	if err != nil {
		return err
	}
	if rowsAffected == 0 {
		return sql.ErrNoRows
	}
	return nil
}

