		VALUES ($1, $2)
		RETURNING id, created_at, updated_at;
	`, name, quantity).Scan(&id, &CreatedAt, &UpdatedAt)
	if err != nil {
		return nil, err
	}

	return &Grocery{
		ID:        id,
		Name:      name,
		Quantity:  quantity,
		CreatedAt: createdAt,
		UpdatedAt: updatedAt,
	}, nil
}

func (db *DB) GetGroceryByID(id uuid.UUID) (*Grocery, error) {
	var grocery Grocery
	err := db.QueryRow(`
		SELECT id, name, quantity, created_at, updated_at FROM groceries WHERE id = $1;
	`, id).Scan(&grocery.ID, &grocery.Name, &grocery.Quantity, &grocery.CreatedAt, &grocery.UpdatedAt)
	if err != nil {
		return nil, err
	}

	return &grocery, nil
}

func (db *DB) ListGroceries() ([]*Grocery, error) {
	rows, err := db.Query(`
		SELECT id, name, quantity, created_at, updated_at FROM groceries;
	`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var groceries []*Grocery
	for rows.Next() {
		var grocery Grocery
		if err := rows.Scan(&grocery.ID, &grocery.Name, &grocery.Quantity, &grocery.CreatedAt, &grocery.UpdatedAt); err != nil {
			return nil, err
		}
		groceries = append(groceries, &grocery)
	}

	if err := rows.Err(); err != nil {
		return nil, err
	}

	return groceries, nil
}

func (db *DB) UpdateGrocery(id uuid.UUID, name string, quantity int) (*Grocery, error) {
	var grocery Grocery
	err := db.QueryRow(`
		UPDATE groceries SET name = $1, quantity = $2, updated_at = NOW()
		WHERE id = $3
		RETURNING id, name, quantity, created_at, updated_at;
	`, name, quantity, id).Scan(&grocery.ID, &grocery.Name, &grocery.Quantity, &grocery.CreatedAt, &grocery.UpdatedAt)
	if err != nil {
		return nil, err
	}

	return &grocery, nil
}

func (db *DB) DeleteGrocery(id uuid.UUID) error {
	_, err := db.Exec(`
		DELETE FROM groceries WHERE id = $1;
	`, id)
	return err
}

