package db

import (
	"database/sql"
	"time"

	"github.com/jmoiron/sqlx"
)

type Grocery struct {
	ID        int       `json:"id"`
	Name      string    `json:"name"`
	Quantity  int       `json:"quantity"`
	CreatedAt time.Time `json:"created_at"`
	UpdatedAt time.Time `json:"updated_at"`
}

func (db *DB) CreateGrocery(name string, quantity int) (*Grocery, error) {
	grocery := &Grocery{
		Name:     name,
		Quantity: quantity,
	}
	query := `
		INSERT INTO groceries (name, quantity)
		VALUES (:name, :quantity)
		RETURNING id, created_at, updated_at
	`
	if err := db.Get(grocery, query, grocery); err != nil {
		return nil, err
	}
	return grocery, nil
}

func (db *DB) GetGroceryByID(id int) (*Grocery, error) {
	grocery := &Grocery{}
	query := `
		SELECT id, name, quantity, created_at, updated_at
		FROM groceries
		WHERE id = $1
	`
	if err := db.Get(grocery, query, id); err != nil {
		return nil, err
	}
	return grocery, nil
}

func (db *DB) ListGroceries() ([]*Grocery, error) {
	var groceries []*Grocery
	query := `
		SELECT id, name, quantity, created_at, updated_at
		FROM groceries
	`
	if err := db.Select(&groceries, query); err != nil {
		return nil, err
	}
	return groceries, nil
}

func (db *DB) UpdateGrocery(id int, name string, quantity int) (*Grocery, error) {
	grocery := &Grocery{
		ID:       id,
		Name:     name,
		Quantity: quantity,
	}
	query := `
		UPDATE groceries
		SET name = :name, quantity = :quantity, updated_at = NOW()
		WHERE id = :id
		RETURNING created_at, updated_at
	`
	if err := db.Get(grocery, query, grocery); err != nil {
		return nil, err
	}
	return grocery, nil
}

func (db *DB) DeleteGrocery(id int) error {
	query := `DELETE FROM groceries WHERE id = $1`
	_, err := db.Exec(query, id)
	return err
}

