package db

import (
	"database/sql"
	"time"

	"github.com/lib/pq"
)

type Grocery struct {
	ID        int       `json:"id"`
	Name      string    `json:"name"`
	Quantity  int       `json:"quantity"`
	CreatedAt time.Time `json:"created_at"`
	UpdatedAt time.Time `json:"updated_at"`
}

func (db *DB) CreateGrocery(name string, quantity int) (*Grocery, error) {
	var grocery Grocery
	err := db.QueryRow(`
		INSERT INTO groceries (name, quantity)
		VALUES ($1, $2)
		RETURNING id, created_at, updated_at
	`, name, quantity).Scan(&grocery.ID, &grocery.CreatedAt, &grocery.UpdatedAt)
	if err != nil {
		return nil, err
	}
	grocery.Name = name
	grocery.Quantity = quantity
	return &grocery, nil
}

func (db *DB) GetGroceryByID(id int) (*Grocery, error) {
	var grocery Grocery
	err := db.QueryRow(`
		SELECT id, name, quantity, created_at, updated_at
		FROM groceries
		WHERE id = $1
	`, id).Scan(&grocery.ID, &grocery.Name, &grocery.Quantity, &grocery.CreatedAt, &grocery.UpdatedAt)
	if err == sql.ErrNoRows {
		return nil, ErrNotFound
	}
	if err != nil {
		return nil, err
	}
	return &grocery, nil
}

func (db *DB) ListGroceries() ([]*Grocery, error) {
	rows, err := db.Query(`
		SELECT id, name, quantity, created_at, updated_at
		FROM groceries
	`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var groceries []*Grocery
	for rows.Next() {
		var grocery Grocery
		err := rows.Scan(&grocery.ID, &grocery.Name, &grocery.Quantity, &grocery.CreatedAt, &grocery.UpdatedAt)
		if err != nil {
			return nil, err
		}
		groceries = append(groceries, &grocery)
	}
	if err = rows.Err(); err != nil {
		return nil, err
	}

	return groceries, nil
}

func (db *DB) UpdateGrocery(id int, name string, quantity int) (*Grocery, error) {
	var grocery Grocery
	err := db.QueryRow(`
		UPDATE groceries
		SET name = $2, quantity = $3, updated_at = CURRENT_TIMESTAMP
		WHERE id = $1
		RETURNING id, name, quantity, created_at, updated_at
	`, id, name, quantity).Scan(&grocery.ID, &grocery.Name, &grocery.Quantity, &grocery.CreatedAt, &grocery.UpdatedAt)
	if err == sql.ErrNoRows {
		return nil, ErrNotFound
	}
	if err != nil {
		return nil, err
	}
	return &grocery, nil
}

func (db *DB) DeleteGrocery(id int) error {
	result, err := db.Exec(`
		DELETE FROM groceries
		WHERE id = $1
	`, id)
	if err != nil {
		return err
	}
	rowsAffected, err := result.RowsAffected()
	if err != nil {
		return err
	}
	if rowsAffected == 0 {
		return ErrNotFound
	}
	return nil
}

