	Name      string    `json:"name"`
	Quantity  int       `json:"quantity"`
	CreatedAt sql.NullTime `json:"created_at"`
	UpdatedAt sql.NullTime `json:"updated_at"`
}

func NewDB(dbPath string) (*sql.DB, error) {
	db, err := sql.Open("sqlite3", dbPath)
	if err != nil {
		return nil, fmt.Errorf("failed to open database: %w", err)
	}
	return db, nil
}

func (db *sql.DB) CreateGrocery(grocery *Grocery) error {
	result, err := db.Exec(`INSERT INTO groceries (name, quantity) VALUES (?, ?)`, grocery.Name, grocery.Quantity)
	if err != nil {
		return fmt.Errorf("failed to create grocery: %w", err)
	}
	id, err := result.LastInsertId()
	if err != nil {
		return fmt.Errorf("failed to get last insert id: %w", err)
	}
	grocery.ID = int(id)
	return nil
}

func (db *sql.DB) GetGroceryByID(id int) (*Grocery, error) {
	var grocery Grocery
	err := db.QueryRow(`SELECT id, name, quantity, created_at, updated_at FROM groceries WHERE id = ?`, id).Scan(
		&grocery.ID,
		&grocery.Name,
		&grocery.Quantity,
		&grocery.CreatedAt,
		&grocery.UpdatedAt,
	)
	if err != nil {
		if err == sql.ErrNoRows {
			return nil, fmt.Errorf("grocery not found: %w", err)
		}
		return nil, fmt.Errorf("failed to get grocery by id: %w", err)
	}
	return &grocery, nil
}

func (db *sql.DB) ListGroceries() ([]*Grocery, error) {
	rows, err := db.Query(`SELECT id, name, quantity, created_at, updated_at FROM groceries`)
	if err != nil {
		return nil, fmt.Errorf("failed to list groceries: %w", err)
	}
	defer rows.Close()

	var groceries []*Grocery
	for rows.Next() {
		var grocery Grocery
		err := rows.Scan(
			&grocery.ID,
			&grocery.Name,
			&grocery.Quantity,
			&grocery.CreatedAt,
			&grocery.UpdatedAt,
		)
		if err != nil {
			return nil, fmt.Errorf("failed to scan grocery row: %w", err)
		}
		groceries = append(groceries, &grocery)
	}

	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("error during iteration over rows: %w", err)
	}

	return groceries, nil
}

func (db *sql.DB) UpdateGroceryByID(id int, grocery *Grocery) error {
	result, err := db.Exec(`UPDATE groceries SET name = ?, quantity = ? WHERE id = ?`, grocery.Name, grocery.Quantity, id)
	if err != nil {
		return fmt.Errorf("failed to update grocery: %w", err)
	}
	rowsAffected, err := result.RowsAffected()
	if err != nil {
		return fmt.Errorf("failed to get rows affected: %w", err)
	}
	if rowsAffected == 0 {
		return fmt.Errorf("grocery not found")
	}
	return nil
}

func (db *sql.DB) DeleteGroceryByID(id int) error {
	result, err := db.Exec(`DELETE FROM groceries WHERE id = ?`, id)
	if err != nil {
		return fmt.Errorf("failed to delete grocery: %w", err)
	}
	rowsAffected, err := result.RowsAffected()
	if err != nil {
		return fmt.Errorf("failed to get rows affected: %w", err)
	}
	if rowsAffected == 0 {
		return fmt.Errorf("grocery not found")
	}
	return nil
}

