package db

import (
	"database/sql"
	"time"

	_ "github.com/mattn/go-sqlite3"
)

type Grocery struct {
	ID        int       `json:"id"`
	Name      string    `json:"name"`
	Quantity  int       `json:"quantity"`
	CreatedAt time.Time `json:"created_at"`
	UpdatedAt time.Time `json:"updated_at"`
}

func OpenDB(dataSourceName string) (*sql.DB, error) {
	return sql.Open("sqlite3", dataSourceName)
}

func CreateGrocery(db *sql.DB, name string, quantity int) (int64, error) {
	result, err := db.Exec(`
		INSERT INTO groceries (name, quantity) VALUES (?, ?)
	`, name, quantity)
	if err != nil {
		return 0, err
	}
	return result.LastInsertId()
}

func GetGrocery(db *sql.DB, id int) (*Grocery, error) {
	var grocery Grocery
	err := db.QueryRow(`
		SELECT id, name, quantity, created_at, updated_at FROM groceries WHERE id = ?
	`, id).Scan(&grocery.ID, &grocery.Name, &grocery.Quantity, &grocery.CreatedAt, &grocery.UpdatedAt)
	if err == sql.ErrNoRows {
		return nil, ErrNotFound
	}
	return &grocery, err
}

func ListGroceries(db *sql.DB) ([]*Grocery, error) {
	rows, err := db.Query(`
		SELECT id, name, quantity, created_at, updated_at FROM groceries
	`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var groceries []*Grocery
	for rows.Next() {
		var grocery Grocery
		if err := rows.Scan(&grocery.ID, &grocery.Name, &grocery.Quantity, &grocery.CreatedAt, &grocery.UpdatedAt); err != nil {
			return nil, err
		}
		groceries = append(groceries, &grocery)
	}

	return groceries, rows.Err()
}

func UpdateGrocery(db *sql.DB, id int, name string, quantity int) error {
	_, err := db.Exec(`
		UPDATE groceries SET name = ?, quantity = ?, updated_at = datetime('now') WHERE id = ?
	`, name, quantity, id)
	if err != nil {
		return err
	}
	return nil
}

func DeleteGrocery(db *sql.DB, id int) error {
	_, err := db.Exec(`
		DELETE FROM groceries WHERE id = ?
	`, id)
	if err != nil {
		return err
	}
	return nil
}

