		{"GET", "/groceries/1", nil, http.StatusOK},
		{"PUT", "/groceries/1", jsonPayload("kiwis", 4), http.StatusOK},
		{"DELETE", "/groceries/1", nil, http.StatusNoContent},
	}

	for _, test := range tests {
