package db

import (
	"database/sql"
	"log"

	_ "github.com/mattn/go-sqlite3"
)

var db *sql.DB

func InitDB(dataSourceName string) error {
	var err error
	db, err = sql.Open("sqlite3", dataSourceName)
	if err != nil {
		return err
	}
	return nil
}

func CloseDB() {
	if db != nil {
		db.Close()
	}
}

type Grocery struct {
	ID        int       `json:"id"`
	Name      string    `json:"name"`
	Quantity  int       `json:"quantity"`
	CreatedAt string    `json:"created_at"`
	UpdatedAt string    `json:"updated_at"`
}

func CreateGrocery(name string, quantity int) (*Grocery, error) {
	query := "INSERT INTO groceries (name, quantity) VALUES (?, ?)"
	result, err := db.Exec(query, name, quantity)
	if err != nil {
		return nil, err
	}
	id, err := result.LastInsertId()
	if err != nil {
		return nil, err
	}
	return &Grocery{
		ID:       int(id),
		Name:     name,
		Quantity: quantity,
	}, nil
}

func GetGroceryByID(id int) (*Grocery, error) {
	query := "SELECT id, name, quantity, created_at, updated_at FROM groceries WHERE id = ?"
	var grocery Grocery
	err := db.QueryRow(query, id).Scan(&grocery.ID, &grocery.Name, &grocery.Quantity, &grocery.CreatedAt, &grocery.UpdatedAt)
	if err != nil {
		if err == sql.ErrNoRows {
			return nil, nil
		}
		return nil, err
	}
	return &grocery, nil
}

func ListGroceries() ([]Grocery, error) {
	query := "SELECT id, name, quantity, created_at, updated_at FROM groceries"
	rows, err := db.Query(query)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var groceries []Grocery
	for rows.Next() {
		var grocery Grocery
		err := rows.Scan(&grocery.ID, &grocery.Name, &grocery.Quantity, &grocery.CreatedAt, &grocery.UpdatedAt)
		if err != nil {
			return nil, err
		}
		groceries = append(groceries, grocery)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}

	return groceries, nil
}

func UpdateGrocery(id int, name string, quantity int) error {
	query := "UPDATE groceries SET name = ?, quantity = ? WHERE id = ?"
	_, err := db.Exec(query, name, quantity, id)
	if err != nil {
		return err
	}
	return nil
}

func DeleteGroceryByID(id int) error {
	query := "DELETE FROM groceries WHERE id = ?"
	_, err := db.Exec(query, id)
	if err != nil {
		return err
	}
	return nil
}

