	"go.uber.org/zap"
	"yourapp/db"
)

type GroceriesHandler struct {
	db *db.DB
	log *zap.SugaredLogger
}

func NewGroceriesHandler(db *db.DB, log *zap.SugaredLogger) *GroceriesHandler {
	return &GroceriesHandler{db, log}
}

func (h *GroceriesHandler) Create(w http.ResponseWriter, r *http.Request, _ httprouter.Params) {
	var grocery db.Grocery
	if err := json.NewDecoder(r.Body).Decode(&grocery); err != nil {
		http.Error(w, "Invalid request body", http.StatusBadRequest)
		return
	}

	newGrocery, err := h.db.CreateGrocery(grocery.Name, grocery.Quantity)
	if err != nil {
		h.log.Errorf("Error creating grocery: %v", err)
		http.Error(w, "Failed to create grocery", http.StatusInternalServerError)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(newGrocery)
}

func (h *GroceriesHandler) Get(w http.ResponseWriter, r *http.Request, ps httprouter.Params) {
	id := ps.ByName("id")

	grocery, err := h.db.GetGrocery(id)
	if err != nil {
		h.log.Errorf("Error getting grocery: %v", err)
		http.Error(w, "Grocery not found", http.StatusNotFound)
