package db

import (
	"database/sql"
	"time"

	"github.com/jmoiron/sqlx"
)

type Grocery struct {
	ID        int       `json:"id"`
	Name      string    `json:"name"`
	Quantity  int       `json:"quantity"`
	CreatedAt time.Time `json:"created_at"`
	UpdatedAt time.Time `json:"updated_at"`
}

func (db *DB) GetAllGroceries() ([]*Grocery, error) {
	var groceries []*Grocery
	err := db.Select(&groceries, "SELECT * FROM groceries")
	return groceries, err
}

func (db *DB) GetGroceryByID(id int) (*Grocery, error) {
	grocery := &Grocery{}
	err := db.Get(grocery, "SELECT * FROM groceries WHERE id=$1", id)
	if err == sql.ErrNoRows {
		return nil, nil
	}
	return grocery, err
}

func (db *DB) CreateGrocery(name string, quantity int) (*Grocery, error) {
	grocery := &Grocery{
		Name:     name,
		Quantity: quantity,
	}
	result, err := db.Exec("INSERT INTO groceries (name, quantity) VALUES ($1, $2)", grocery.Name, grocery.Quantity)
	if err != nil {
		return nil, err
	}
	id, err := result.LastInsertId()
	if err != nil {
		return nil, err
	}
	grocery.ID = int(id)
	return grocery, db.Get(grocery, "SELECT * FROM groceries WHERE id=$1", grocery.ID)
}

func (db *DB) UpdateGrocery(id int, name string, quantity int) (*Grocery, error) {
	grocery := &Grocery{
		ID:       id,
		Name:     name,
		Quantity: quantity,
	}
	_, err := db.Exec("UPDATE groceries SET name=$1, quantity=$2 WHERE id=$3", grocery.Name, grocery.Quantity, grocery.ID)
	if err != nil {
		return nil, err
	}
	return grocery, db.Get(grocery, "SELECT * FROM groceries WHERE id=$1", grocery.ID)
}

func (db *DB) DeleteGrocery(id int) error {
	_, err := db.Exec("DELETE FROM groceries WHERE id=$1", id)
	return err
}

