package db

import (
	"database/sql"
	"time"

	_ "github.com/lib/pq"
)

type Grocery struct {
	ID        int       `json:"id"`
	Name      string    `json:"name"`
	Quantity  int       `json:"quantity"`
	CreatedAt time.Time `json:"created_at"`
	UpdatedAt time.Time `json:"updated_at"`
}

func ConnectDB(dataSourceName string) (*sql.DB, error) {
	db, err := sql.Open("postgres", dataSourceName)
	if err != nil {
		return nil, err
	}
	return db, nil
}

func GetGroceries(db *sql.DB) ([]Grocery, error) {
	rows, err := db.Query(`SELECT id, name, quantity, created_at, updated_at FROM groceries`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var groceries []Grocery
	for rows.Next() {
		var grocery Grocery
		err := rows.Scan(&grocery.ID, &grocery.Name, &grocery.Quantity, &grocery.CreatedAt, &grocery.UpdatedAt)
		if err != nil {
			return nil, err
		}
		groceries = append(groceries, grocery)
	}
	return groceries, nil
}

func GetGroceryByID(db *sql.DB, id int) (Grocery, error) {
	var grocery Grocery
	err := db.QueryRow(`SELECT id, name, quantity, created_at, updated_at FROM groceries WHERE id = $1`, id).Scan(&grocery.ID, &grocery.Name, &grocery.Quantity, &grocery.CreatedAt, &grocery.UpdatedAt)
	if err != nil {
		return grocery, err
	}
	return grocery, nil
}

func CreateGrocery(db *sql.DB, name string, quantity int) (int, error) {
	var id int
	err := db.QueryRow(`INSERT INTO groceries (name, quantity) VALUES ($1, $2) RETURNING id`, name, quantity).Scan(&id)
	if err != nil {
		return 0, err
	}
	return id, nil
}

func UpdateGrocery(db *sql.DB, id int, name string, quantity int) error {
	_, err := db.Exec(`UPDATE groceries SET name = $1, quantity = $2 WHERE id = $3`, name, quantity, id)
	if err != nil {
		return err
	}
	return nil
}

func DeleteGrocery(db *sql.DB, id int) error {
	_, err := db.Exec(`DELETE FROM groceries WHERE id = $1`, id)
	if err != nil {
		return err
	}
	return nil
}

