package db

import (
	"database/sql"
	"fmt"

	_ "github.com/lib/pq"
)

type Grocery struct {
	ID         int       `json:"id"`
	Name       string    `json:"name"`
	Quantity   int       `json:"quantity"`
	CreatedAt  sql.NullTime `json:"created_at"`
	UpdatedAt  sql.NullTime `json:"updated_at"`
}

func (d *DB) CreateGrocery(name string, quantity int) (*Grocery, error) {
	query := `
		INSERT INTO groceries (name, quantity)
		VALUES ($1, $2)
		RETURNING id, created_at, updated_at
	`
	var grocery Grocery
	err := d.db.QueryRow(query, name, quantity).Scan(&grocery.ID, &grocery.CreatedAt, &grocery.UpdatedAt)
	if err != nil {
		return nil, fmt.Errorf("error creating grocery: %v", err)
	}
	grocery.Name = name
	grocery.Quantity = quantity
	return &grocery, nil
}

func (d *DB) GetGroceryByID(id int) (*Grocery, error) {
	query := `
		SELECT id, name, quantity, created_at, updated_at
		FROM groceries
		WHERE id = $1
	`
	var grocery Grocery
	err := d.db.QueryRow(query, id).Scan(&grocery.ID, &grocery.Name, &grocery.Quantity, &grocery.CreatedAt, &grocery.UpdatedAt)
	if err == sql.ErrNoRows {
		return nil, fmt.Errorf("grocery not found: %v", err)
	} else if err != nil {
		return nil, fmt.Errorf("error getting grocery: %v", err)
	}
	return &grocery, nil
}

func (d *DB) ListGroceries() ([]*Grocery, error) {
	query := `
		SELECT id, name, quantity, created_at, updated_at
		FROM groceries
	`
	rows, err := d.db.Query(query)
	if err != nil {
		return nil, fmt.Errorf("error listing groceries: %v", err)
	}
	defer rows.Close()

	var groceries []*Grocery
	for rows.Next() {
		var grocery Grocery
		err := rows.Scan(&grocery.ID, &grocery.Name, &grocery.Quantity, &grocery.CreatedAt, &grocery.UpdatedAt)
		if err != nil {
			return nil, fmt.Errorf("error scanning row: %v", err)
		}
		groceries = append(groceries, &grocery)
	}

	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("error iterating over rows: %v", err)
	}

	return groceries, nil
}

func (d *DB) UpdateGrocery(id int, name string, quantity int) (*Grocery, error) {
	query := `
		UPDATE groceries
		SET name = $2, quantity = $3, updated_at = NOW()
		WHERE id = $1
		RETURNING id, created_at, updated_at
	`
	var grocery Grocery
	err := d.db.QueryRow(query, id, name, quantity).Scan(&grocery.ID, &grocery.CreatedAt, &grocery.UpdatedAt)
	if err == sql.ErrNoRows {
		return nil, fmt.Errorf("grocery not found: %v", err)
	} else if err != nil {
		return nil, fmt.Errorf("error updating grocery: %v", err)
	}
	grocery.Name = name
	grocery.Quantity = quantity
	return &grocery, nil
}

func (d *DB) DeleteGrocery(id int) error {
	query := `
		DELETE FROM groceries
		WHERE id = $1
	`
	_, err := d.db.Exec(query, id)
	if err == sql.ErrNoRows {
		return fmt.Errorf("grocery not found: %v", err)
	} else if err != nil {
		return fmt.Errorf("error deleting grocery: %v", err)
	}
	return nil
}

