	CreatedAt  time.Time `json:"created_at"`
	UpdatedAt  time.Time `json:"updated_at"`
}

func OpenDB() (*sql.DB, error) {
	db, err := sql.Open("sqlite3", "./groceries.db")
	if err != nil {
		return nil, err
	}
	return db, nil
}

func CreateGrocery(db *sql.DB, name string, quantity int) (int64, error) {
	result, err := db.Exec(
		"INSERT INTO groceries (name, quantity) VALUES (?, ?)",
		name, quantity,
	)
	if err != nil {
		return 0, err
	}
	id, err := result.LastInsertId()
	if err != nil {
		return 0, err
	}
	return id, nil
}

func GetGrocery(db *sql.DB, id int) (*Grocery, error) {
	var grocery Grocery
	err := db.QueryRow(
		"SELECT id, name, quantity, created_at, updated_at FROM groceries WHERE id = ?",
		id,
	).Scan(&grocery.ID, &grocery.Name, &grocery.Quantity, &grocery.CreatedAt, &grocery.UpdatedAt)
	if err != nil {
		if err == sql.ErrNoRows {
			return nil, fmt.Errorf("404")
		}
		return nil, err
	}
	return &grocery, nil
}

func ListGroceries(db *sql.DB) ([]*Grocery, error) {
	rows, err := db.Query(
		"SELECT id, name, quantity, created_at, updated_at FROM groceries",
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var groceries []*Grocery
	for rows.Next() {
		var grocery Grocery
		err := rows.Scan(&grocery.ID, &grocery.Name, &grocery.Quantity, &grocery.CreatedAt, &grocery.UpdatedAt)
		if err != nil {
			return nil, err
		}
		groceries = append(groceries, &grocery)
	}

	if err = rows.Err(); err != nil {
		return nil, err
	}
	return groceries, nil
}

func UpdateGrocery(db *sql.DB, id int, name string, quantity int) error {
	_, err := db.Exec(
		"UPDATE groceries SET name = ?, quantity = ? WHERE id = ?",
		name, quantity, id,
	)
	if err != nil {
		return err
	}
	return nil
}

func DeleteGrocery(db *sql.DB, id int) error {
	_, err := db.Exec("DELETE FROM groceries WHERE id = ?", id)
	if err != nil {
		return err
	}
	return nil
}

