}

func NewGroceryDB(dsn string) (*sql.DB, error) {
	db, err := sql.Open("postgres", dsn)
	if err != nil {
		return nil, fmt.Errorf("failed to connect to database: %w", err)
	}
	return db, nil
}

func (db *sql.DB) GetGroceryByID(id int) (*Grocery, error) {
	var g Grocery
	err := db.QueryRow(`SELECT id, name, quantity, created_at, updated_at FROM groceries WHERE id = $1`, id).Scan(&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt)
	if err == sql.ErrNoRows {
		return nil, fmt.Errorf("grocery not found")
	}
	if err != nil {
		return nil, fmt.Errorf("failed to get grocery: %w", err)
	}
	return &g, nil
}

func (db *sql.DB) ListGroceries() ([]*Grocery, error) {
	rows, err := db.Query(`SELECT id, name, quantity, created_at, updated_at FROM groceries`)
	if err != nil {
		return nil, fmt.Errorf("failed to list groceries: %w", err)
	}
	defer rows.Close()

	var groceries []*Grocery
	for rows.Next() {
		var g Grocery
		if err := rows.Scan(&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt); err != nil {
			return nil, fmt.Errorf("failed to scan grocery row: %w", err)
		}
		groceries = append(groceries, &g)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("failed to iterate over groceries rows: %w", err)
	}
	return groceries, nil
}

func (db *sql.DB) CreateGrocery(name string, quantity int) (*Grocery, error) {
	var g Grocery
	err := db.QueryRow(`INSERT INTO groceries (name, quantity) VALUES ($1, $2) RETURNING id, name, quantity, created_at, updated_at`, name, quantity).Scan(&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt)
	if err != nil {
		return nil, fmt.Errorf("failed to create grocery: %w", err)
	}
	return &g, nil
}

func (db *sql.DB) UpdateGrocery(id int, name string, quantity int) (*Grocery, error) {
	var g Grocery
	err := db.QueryRow(`UPDATE groceries SET name = $1, quantity = $2 WHERE id = $3 RETURNING id, name, quantity, created_at, updated_at`, name, quantity, id).Scan(&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt)
	if err == sql.ErrNoRows {
		return nil, fmt.Errorf("grocery not found")
	}
	if err != nil {
		return nil, fmt.Errorf("failed to update grocery: %w", err)
	}
	return &g, nil
}

func (db *sql.DB) DeleteGrocery(id int) error {
	result, err := db.Exec(`DELETE FROM groceries WHERE id = $1`, id)
	if err != nil {
		return fmt.Errorf("failed to delete grocery: %w", err)
	}
	rowsAffected, err := result.RowsAffected()
	if err != nil {
		return fmt.Errorf("failed to get rows affected: %w", err)
	}
	if rowsAffected == 0 {
		return fmt.Errorf("grocery not found")
	}
	return nil
}

