package db

import (
	"database/sql"
	"time"

	"github.com/jmoiron/sqlx"
)

type Grocery struct {
	ID        int       `db:"id"`
	Name      string    `db:"name"`
	Quantity  int       `db:"quantity"`
	CreatedAt time.Time `db:"created_at"`
	UpdatedAt time.Time `db:"updated_at"`
}

func CreateGrocery(db *sqlx.DB, name string, quantity int) (*Grocery, error) {
	grocery := &Grocery{Name: name, Quantity: quantity}
	query := `
		INSERT INTO groceries (name, quantity)
		VALUES (:name, :quantity)
		RETURNING id, created_at, updated_at
	`
	if err := db.Get(grocery, query, grocery); err != nil {
		return nil, err
	}
	return grocery, nil
}

func GetGrocery(db *sqlx.DB, id int) (*Grocery, error) {
	grocery := &Grocery{}
	query := `SELECT * FROM groceries WHERE id = $1`
	err := db.Get(grocery, query, id)
	if err == sql.ErrNoRows {
		return nil, nil
	}
	return grocery, err
}

func ListGroceries(db *sqlx.DB) ([]*Grocery, error) {
	groceries := []*Grocery{}
	query := `SELECT * FROM groceries`
	err := db.Select(&groceries, query)
	return groceries, err
}

func UpdateGrocery(db *sqlx.DB, id int, name string, quantity int) (*Grocery, error) {
	grocery := &Grocery{ID: id, Name: name, Quantity: quantity}
	query := `
		UPDATE groceries
		SET name = :name, quantity = :quantity
		WHERE id = :id
		RETURNING created_at, updated_at
	`
	if err := db.Get(grocery, query, grocery); err != nil {
		return nil, err
	}
	return grocery, nil
}

func DeleteGrocery(db *sqlx.DB, id int) error {
	query := `DELETE FROM groceries WHERE id = $1`
	_, err := db.Exec(query, id)
	return err
}

