package db

import (
	"database/sql"
	"log"
)

type Grocery struct {
	ID        int       `json:"id"`
	Name      string    `json:"name"`
	Quantity  int       `json:"quantity"`
	CreatedAt sql.NullTime `json:"created_at"`
	UpdatedAt sql.NullTime `json:"updated_at"`
}

func (g *Grocery) GetByID(db *sql.DB, id int) error {
	return db.QueryRow(`SELECT id, name, quantity, created_at, updated_at FROM groceries WHERE id = $1`, id).Scan(&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt)
}

func (g *Grocery) Create(db *sql.DB) error {
	return db.QueryRow(`INSERT INTO groceries (name, quantity) VALUES ($1, $2) RETURNING id`, g.Name, g.Quantity).Scan(&g.ID)
}

func (g *Grocery) Update(db *sql.DB) error {
	_, err := db.Exec(`UPDATE groceries SET name = $1, quantity = $2 WHERE id = $3`, g.Name, g.Quantity, g.ID)
	return err
}

func (g *Grocery) Delete(db *sql.DB) error {
	_, err := db.Exec(`DELETE FROM groceries WHERE id = $1`, g.ID)
	return err
}

func ListGroceries(db *sql.DB) ([]Grocery, error) {
	rows, err := db.Query(`SELECT id, name, quantity, created_at, updated_at FROM groceries`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	groceries := []Grocery{}
	for rows.Next() {
		var g Grocery
		err = rows.Scan(&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt)
		if err != nil {
			return nil, err
		}
		groceries = append(groceries, g)
	}

	if err := rows.Err(); err != nil {
		return nil, err
	}

	return groceries, nil
}

