func TestGroceryCRUD(t *testing.T) {
	db := setupDB(t)
	defer teardownDB(db)

	g := &Grocery{Name: "Bananas", Quantity: 6}

	// Create
	if err := g.Create(db); err != nil {
		t.Fatalf("Error creating grocery: %v", err)
	}
	if g.ID == 0 {
		t.Fatal("ID not set after create")
	}

	// Read by ID
	g2 := &Grocery{ID: g.ID}
	if err := g2.GetByID(db, g.ID); err != nil {
		t.Fatalf("Error getting grocery by ID: %v", err)
	}
	if g.Name != g2.Name || g.Quantity != g2.Quantity {
		t.Fatal("Read grocery does not match created")
	}

	// Update
	g2.Name = "Apples"
	g2.Quantity = 10
	if err := g2.Update(db); err != nil {
		t.Fatalf("Error updating grocery: %v", err)
	}
	var updatedGrocery Grocery
	if err := updatedGrocery.GetByID(db, g.ID); err != nil {
		t.Fatalf("Error getting updated grocery by ID: %v", err)
	}
	if updatedGrocery.Name != "Apples" || updatedGrocery.Quantity != 10 {
		t.Fatal("Update did not stick")
	}

	// Delete
	if err := updatedGrocery.Delete(db); err != nil {
		t.Fatalf("Error deleting grocery: %v", err)
	}
	var deletedGrocery Grocery
	err := deletedGrocery.GetByID(db, g.ID)
	if err == nil || err.Error() != "sql: no rows in result set" {
		t.Fatal("Delete did not delete")
	}

	// List
	groceries, err := ListGroceries(db)
	if err != nil {
		t.Fatalf("Error listing groceries: %v", err)
	}
	if len(groceries) != 0 {
		t.Fatal("List should be empty after delete")
	}
}

