package handlers

import (
	"encoding/json"
	"net/http"

	"github.com/julienschmidt/httprouter"
	"example.com/groceryapp/db"
)

func GroceriesHandler(db *sql.DB) httprouter.Handle {
	return func(w http.ResponseWriter, r *http.Request, ps httprouter.Params) {
		switch r.Method {
		case http.MethodGet:
			groceries, err := db.ListGroceries()
			if err != nil {
				http.Error(w, "Internal Server Error", http.StatusInternalServerError)
				return
			}
			json.NewEncoder(w).Encode(groceries)

		case http.MethodPost:
			var g db.Grocery
			err := json.NewDecoder(r.Body).Decode(&g)
			if err != nil {
				http.Error(w, "Bad Request", http.StatusBadRequest)
				return
			}
			if err := g.Create(db); err != nil {
				http.Error(w, "Internal Server Error", http.StatusInternalServerError)
				return
			}
			w.WriteHeader(http.StatusCreated)
			json.NewEncoder(w).Encode(g)

		default:
			http.Error(w, "Method Not Allowed", http.StatusMethodNotAllowed)
		}
	}
}

func GroceryHandler(db *sql.DB) httprouter.Handle {
	return func(w http.ResponseWriter, r *http.Request, ps httprouter.Params) {
		id, err := strconv.Atoi(ps.ByName("id"))
		if err != nil {
			http.Error(w, "Bad Request", http.StatusBadRequest)
			return
		}

		g := &db.Grocery{ID: id}
		switch r.Method {
		case http.MethodGet:
			err := g.GetByID(db, id)
			if err == sql.ErrNoRows {
				http.Error(w, "Not Found", http.StatusNotFound)
				return
			} else if err != nil {
				http.Error(w, "Internal Server Error", http.StatusInternalServerError)
				return
			}
			json.NewEncoder(w).Encode(g)

		case http.MethodPut:
			err := json.NewDecoder(r.Body).Decode(&g)
			if err != nil {
				http.Error(w, "Bad Request", http.StatusBadRequest)
				return
			}
			g.ID = id // Ensure the ID is used from the URL
			if err := g.Update(db); err != nil {
				http.Error(w, "Internal Server Error", http.StatusInternalServerError)
				return
			}
			json.NewEncoder(w).Encode(g)

		case http.MethodDelete:
			err := g.Delete(db)
			if err == sql.ErrNoRows {
				http.Error(w, "Not Found", http.StatusNotFound)
				return
			} else if err != nil {
				http.Error(w, "Internal Server Error", http.StatusInternalServerError)
				return
			}
			w.WriteHeader(http.StatusNoContent)

		default:
			http.Error(w, "Method Not Allowed", http.StatusMethodNotAllowed)
		}
	}
}

