	req, _ := http.NewRequest("POST", "/groceries", bytes.NewBuffer([]byte(`{"name": "Bananas", "quantity": 6}`)))
	resp, err := router.Test(req)
	if err != nil {
		t.Fatalf("Error making POST request: %v", err)
	}
	defer resp.Body.Close()
	var createdGrocery db.Grocery
	err = json.NewDecoder(resp.Body).Decode(&createdGrocery)
	if err != nil {
		t.Fatalf("Error decoding response body: %v", err)
	}

	groceryID := fmt.Sprintf("%d", createdGrocery.ID)

	// Get by ID
	req, _ = http.NewRequest("GET", "/groceries/"+groceryID, nil)
	resp, err = router.Test(req)
	if err != nil {
		t.Fatalf("Error making GET request: %v", err)
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		t.Errorf("Expected status code %d, got %d", http.StatusOK, resp.StatusCode)
	}

	var retrievedGrocery db.Grocery
	err = json.NewDecoder(resp.Body).Decode(&retrievedGrocery)
	if err != nil {
		t.Fatalf("Error decoding response body: %v", err)
	}
	if retrievedGrocery.Name != "Bananas" || retrievedGrocery.Quantity != 6 {
		t.Fatal("Retrieved grocery does not match created")
	}

	// Update
	req, _ = http.NewRequest("PUT", "/groceries/"+groceryID, bytes.NewBuffer([]byte(`{"name": "Apples", "quantity": 10}`)))
	resp, err = router.Test(req)
	if err != nil {
		t.Fatalf("Error making PUT request: %v", err)
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		t.Errorf("Expected status code %d, got %d", http.StatusOK, resp.StatusCode)
	}

	var updatedGrocery db.Grocery
	err = json.NewDecoder(resp.Body).Decode(&updatedGrocery)
	if err != nil {
		t.Fatalf("Error decoding response body: %v", err)
	}
	if updatedGrocery.Name != "Apples" || updatedGrocery.Quantity != 10 {
		t.Fatal("Updated grocery does not match update request")
	}

	// Delete
	req, _ = http.NewRequest("DELETE", "/groceries/"+groceryID, nil)
	resp, err = router.Test(req)
	if err != nil {
		t.Fatalf("Error making DELETE request: %v", err)
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusNoContent {
		t.Errorf("Expected status code %d, got %d", http.StatusNoContent, resp.StatusCode)
	}

	// Get by ID after delete (should be 404)
	req, _ = http.NewRequest("GET", "/groceries/"+groceryID, nil)
	resp, err = router.Test(req)
	if err != nil {
		t.Fatalf("Error making GET request: %v", err)
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusNotFound {
		t.Errorf("Expected status code %d, got %d", http.StatusNotFound, resp.StatusCode)
	}
}

