package main

import (
	"log"
	"net/http"
	"os"

	"github.com/julienschmidt/httprouter"
	"example.com/groceryapp/db"
)

func main() {
	db, err := sql.Open("postgres", os.Getenv("DATABASE_URL"))
	if err != nil {
		log.Fatalf("Error connecting to database: %v", err)
	}
	defer db.Close()

	router := httprouter.New()
	router.GET("/groceries", handlers.GroceriesHandler(db))
	router.POST("/groceries", handlers.GroceriesHandler(db))
	router.GET("/groceries/:id", handlers.GroceryHandler(db))
	router.PUT("/groceries/:id", handlers.GroceryHandler(db))
	router.DELETE("/groceries/:id", handlers.GroceryHandler(db))

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}

	log.Printf("Starting server on port %s", port)
	err = http.ListenAndServe(":"+port, router)
	if err != nil {
		log.Fatalf("Error starting server: %v", err)
	}
}
